<script setup lang="ts">
import { dateUTC, duration, itemLabel, statusLabel } from '@/types/leaderboard';
import type { RunFacts } from '@/types/leaderboard';
defineProps<{ run: RunFacts }>();
const bonusLabel: Record<string, string> = { damage: 'Damage', maximum_health: 'Maximum HP', movement_speed: 'Speed', pickup_radius: 'Pickup', ability_area: 'Ability area', cooldown_reduction: 'Cooldown reduction', damage_reduction: 'Incoming damage reduction', experience_gain: 'In-run experience' };
const abilityLabel: Record<string, string> = { fireball: 'Fireball', frost: 'Frost Nova', lightning: 'Chain Lightning', meteor: 'Armageddon', shield: 'Arcane Shield', cleave: 'Cleave', whirlwind: 'Whirlwind', slam: 'Ground Stomp', blades: 'Piercing Throw', iron: 'Shield Block' };
</script>
<template><div class="run-facts"><div class="rank-stats"><article><small>GAME SCORE</small><strong>{{ run.score.toLocaleString('en-US') }}</strong></article><article><small>CHARACTER</small><strong>{{ run.character === 'warrior' ? 'Warrior' : 'Mage' }}</strong></article><article><small>KILLS / TIME</small><strong>{{ run.kills }} / {{ duration(run.elapsed) }}</strong></article><article><small>RESULT</small><strong>{{ run.outcome === 'victory' ? 'Victory' : run.outcome === 'defeat' ? 'Defeat' : '—' }}</strong></article></div><p><span class="run-badge" :data-status="run.status">{{ statusLabel[run.status] ?? run.status }}</span> · {{ run.mode === 'normal' ? 'Regular run' : 'Practice' }} · {{ dateUTC(run.completed_at) }}</p><p v-if="run.manual_review" class="notice">Result accepted after manual review.</p><h2>Consumables and Revive</h2><p>Revives: <strong data-testid="run-revives">{{ run.revives }}</strong>. Consumables are allowed on the shared leaderboard.</p><p v-if="run.premium_actions">Skill Reroll: {{run.premium_actions.skill_reroll??0}} Tokens Resurrection: {{run.premium_actions.resurrection??0}}</p><ul v-if="run.items.length" class="run-items" data-testid="run-items"><li v-for="item in run.items" :key="item.item_id"><strong>{{ itemLabel[item.item_id] ?? item.item_id }} × {{ item.quantity }}</strong><small>Application confirmed by client: {{ item.acknowledged }}</small></li></ul><p v-else class="subtle">No server items were used.</p><p class="subtle">The log confirms item usage. Client confirmation does not verify the integrity of the game simulation.</p><details><summary>Abilities and statistics</summary><ul><li v-for="ability in run.abilities" :key="ability">{{ abilityLabel[ability] ?? ability }}</li></ul><dl class="run-dictionary"><template v-for="(count, kind) in run.by_kind" :key="kind"><dt>{{ kind }}</dt><dd>{{ count }}</dd></template></dl><p>Character XP multiplier at start: {{ run.character_xp_multiplier }}×</p><h3>Permanent bonuses at start</h3><dl class="run-dictionary"><template v-for="(value, key) in run.start_bonuses" :key="key"><dt>{{ bonusLabel[key] ?? key }}</dt><dd>{{ value / 100 }}%</dd></template></dl></details><p class="notice">The server run and submitted statistics were checked for consistency. Gameplay runs in the browser; this does not fully prevent forged results.</p></div></template>
